// --------------------------------------------------
// DASHBOARD DATA
// --------------------------------------------------
router.get("/admin/data", async (req, res) => {
  if (!isAdmin(req)) {
    return res.status(401).json({ error: "Please sign in." });
  }

  try {
    const OFFERS = await getOffers();
    const todayStart = startOfToday();
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

    const summary = await queries.getDashboardSummary(todayStart, sevenDaysAgo);

    const offers = [];
    for (const o of OFFERS) {
      const stats = await queries.getOfferStats(o.minVisits);
      offers.push({
        minVisits: o.minVisits,
        headline: o.headline,
        unlocked: stats.unlocked,
        claimed: stats.claimed
      });
    }

    const claimCounts = await queries.getClaimCountsByUser();
    const customerRows = await queries.getCustomerList(1000);

    const customers = customerRows.map((r) => ({
      email: r.email,
      visits: Number(r.visitCount),
      claimed: claimCounts.get(String(r.id)) || 0,
      joined: toIso(r.createdAt),
      lastVisit: r.lastVisitAt ? toIso(r.lastVisitAt) : null
    }));

    const claimRows = await queries.getRecentClaims(20);
    const recentClaims = claimRows.map((r) => {
      const o = OFFERS.find((x) => Number(x.minVisits) === Number(r.minVisits));
      return {
        email: r.email || "(deleted user)",
        reward: o ? o.headline : `${r.minVisits} visits`,
        claimedAt: toIso(r.claimedAt)
      };
    });

    try {
      if (req.query.refreshReviews === "1") {
        await syncGoogleReviews(true);
      }
    } catch (e) {
      console.log(`Reviews Sync Error: ${e.message}`);
    }

    const gSummary = await queries.getSetting("googleSummary");
    const gRows = await queries.getReviews(50);

    const google = {
      rating: typeof gSummary?.rating === "number" ? gSummary.rating : null,
      count: gSummary?.count ?? 0,
      updatedAt: gSummary?.fetchedAt ? toIso(gSummary.fetchedAt) : null,
      reviews: gRows.map((r) => ({
        author: r.author,
        stars: r.stars,
        text: r.text || "",
        publishedAt: r.publishedAt ? toIso(r.publishedAt) : null
      }))
    };

    res.json({
      adminUser: DASHBOARD_USERNAME,
      summary,
      offers,
      customers,
      recentClaims,
      google
    });
  } catch (e) {
    console.log(`Dashboard Error: ${e.message}`);
    res.status(500).json({ error: "Could not load the dashboard data." });
  }
});

// --------------------------------------------------
// CUSTOMER HISTORY
// --------------------------------------------------
router.get("/admin/customer", async (req, res) => {
  if (!isAdmin(req)) {
    return res.status(401).json({ error: "Please sign in." });
  }

  try {
    const email = String(req.query.email || "").trim().toLowerCase();
    const user = await queries.findUserByEmail(email);

    if (!user) {
      return res.status(404).json({ error: "Customer not found." });
    }

    const OFFERS = await getOffers();
    const [visits, claims] = await Promise.all([
      queries.getUserVisits(user.id, 2000),
      queries.getCustomerClaims(user.id)
    ]);

    res.json({
      email: user.email,
      joined: toIso(user.createdAt),
      firstVisit: visits[0] ? toIso(visits[0].at) : null,
      lastVisit: user.lastVisitAt ? toIso(user.lastVisitAt) : null,
      totalVisits: Number(user.visitCount),
      visits: visits.map((v) => toIso(v.at)),
      claims: claims.map((c) => {
        const o = OFFERS.find((x) => Number(x.minVisits) === Number(c.minVisits));
        return {
          reward: o ? o.headline : `${c.minVisits} visits`,
          claimedAt: toIso(c.claimedAt)
        };
      })
    });
  } catch (e) {
    console.log(`Customer Error: ${e.message}`);
    res.status(500).json({ error: "Could not load this customer." });
  }
});

// --------------------------------------------------
// CSV EXPORT
// --------------------------------------------------
router.get("/admin/export.csv", async (req, res) => {
  if (!isAdmin(req)) {
    return res.status(401).send("Please sign in on the dashboard first.");
  }

  try {
    const claimCounts = await queries.getClaimCountsByUser();
    const rows = await queries.getExportCustomers();

    const cell = (v) => {
      let t = String(v ?? "");
      if (/^[=+\-@]/.test(t)) {
        t = `'${t}`;
      }
      return `"${t.replace(/"/g, '""')}"`;
    };

    const lines = ["Email,Visits,Rewards claimed,Last visit (UTC),Joined (UTC)"];

    for (const r of rows) {
      lines.push(
        [
          r.email,
          r.visitCount,
          claimCounts.get(String(r.id)) || 0,
          r.lastVisitAt ? toIso(r.lastVisitAt) : "",
          toIso(r.createdAt)
        ]
          .map(cell)
          .join(",")
      );
    }

    res.set("Content-Type", "text/csv; charset=utf-8");
    res.set("Content-Disposition", 'attachment; filename="mart-customers.csv"');
    res.send(lines.join("\r\n"));
  } catch (e) {
    console.log(`Export Error: ${e.message}`);
    res.status(500).send("Could not create the file.");
  }
});

module.exports = router;
